package designsystem

import "bytes"

// Stylesheet is the content of the generated design stylesheet that flai
// design css --write writes (S-0385, ADR-0159): a comment header saying it
// is generated from the token file tokens and not to be edited, then
// Tailwind's rendering. The header holds no date or version, so that the
// same tokens always give the same file. "" when Tailwind gives "".
func Stylesheet(sys *System, tokens string) string {
	tw := Tailwind(sys)
	if tw == "" {
		return ""
	}
	return "/* Generated by flai design css --write from " + tokens + ".\n" +
		"   Do not edit: change the tokens and run flai design css --write again. */\n\n" + tw
}

// Stale reports whether content, a generated stylesheet as read, differs
// from what Stylesheet gives for the token file tokens, so that flai check
// can say the stylesheet is out of date (S-0385, ADR-0159). CRLF and LF line
// endings count as the same; every other difference counts.
func Stale(sys *System, tokens string, content []byte) bool {
	return !bytes.Equal(bytes.ReplaceAll(content, []byte("\r\n"), []byte("\n")), []byte(Stylesheet(sys, tokens)))
}
